"use client";

import * as React from "react";

import type {
  QuizDefinition,
  QuizItem,
  QuizResult,
  SubmittedAnswer,
} from "../lib/model";
import { scoreQuiz } from "../lib/grading";
import { createQuizSession, reduceQuizSession } from "../lib/session";
import { validateQuizDefinition } from "../lib/validation";
import {
  Button,
  Card,
  CardAction,
  CardContent,
  CardFooter,
  CardHeader,
  CardTitle,
} from "../ui/primitives";
import {
  Questionnaire,
  QuestionnaireActions,
  QuestionnaireNext,
  QuestionnairePrevious,
  QuestionnaireSubmit,
} from "../ui/Questionnaire";
import { QuizResults } from "./QuizResults";
import { QuizStep } from "./QuizStep";
import { cn } from "../lib/cn";

export interface QuizProps {
  quiz: QuizDefinition;
  className?: string;
  onComplete?: (result: QuizResult) => void;
}

export function Quiz(props: QuizProps): React.JSX.Element {
  const generatedId = React.useId();
  const rootRef = React.useRef<HTMLDivElement>(null);
  const idPrefix = `quiz-${generatedId}`;

  if (!isValidQuiz(props.quiz)) {
    const headingId = `${idPrefix}-unavailable`;
    return (
      <div
        ref={rootRef}
        className={cn(
          "cn-questionnaire rounded-xl border p-6",
          props.className,
        )}
        role="alert"
        aria-labelledby={headingId}
      >
        <h3 id={headingId} className="font-semibold">
          Quiz unavailable
        </h3>
      </div>
    );
  }

  return (
    <div
      ref={rootRef}
      className={cn("cn-questionnaire", props.className)}
      data-quiz-root=""
    >
      <QuizSession
        key={quizSessionKey(props.quiz)}
        quiz={props.quiz}
        idPrefix={idPrefix}
        rootRef={rootRef}
        onComplete={props.onComplete}
      />
    </div>
  );
}

function QuizSession(props: {
  quiz: QuizDefinition;
  idPrefix: string;
  rootRef: React.RefObject<HTMLDivElement | null>;
  onComplete?: (result: QuizResult) => void;
}): React.JSX.Element {
  const [state, dispatch] = React.useReducer(
    (
      current: ReturnType<typeof createQuizSession>,
      action: Parameters<typeof reduceQuizSession>[2],
    ) => reduceQuizSession(props.quiz, current, action),
    props.quiz,
    createQuizSession,
  );
  const resultsHeadingRef = React.useRef<HTMLHeadingElement>(null);
  const previousPhase = React.useRef(state.phase);
  const completionNotified = React.useRef(false);
  const result = React.useMemo(
    () => scoreQuiz(props.quiz, state.answers),
    [props.quiz, state.answers],
  );

  React.useEffect(() => {
    if (state.phase === "complete") {
      resultsHeadingRef.current?.focus();
      if (!completionNotified.current) {
        completionNotified.current = true;
        props.onComplete?.(result);
      }
    } else {
      completionNotified.current = false;
      if (previousPhase.current === "complete") {
        findStep(props.rootRef.current, state.activeItemId)?.focus();
      }
    }
    previousPhase.current = state.phase;
  }, [props.onComplete, props.rootRef, result, state.activeItemId, state.phase]);

  if (state.phase === "complete") {
    return (
      <QuizResults
        definition={props.quiz}
        grades={state.grades}
        onRestart={() => dispatch({ type: "restart" })}
        headingRef={resultsHeadingRef}
      />
    );
  }

  const activeIndex = props.quiz.items.findIndex(
    (item) => item.id === state.activeItemId,
  );
  const activeItem = props.quiz.items[activeIndex];
  const questions = props.quiz.items.filter((item) => item.type !== "info");
  const activeQuestionIndex = activeItem && activeItem.type !== "info"
    ? activeItem.index ?? questions.findIndex((question) => question.id === activeItem.id) + 1
    : undefined;
  const nextItem = props.quiz.items[activeIndex + 1];
  const questionnaireItems = props.quiz.items.map((item) =>
    toQuestionnaireItem(
      item,
      Boolean(state.grades[item.id]),
      formName(props.idPrefix, item.id),
    ),
  );
  const canComplete = props.quiz.items.filter((item) => item.type !== "info").every(
    (item) => state.grades[item.id] !== undefined,
  );
  const activeAnswer = activeItem ? state.answers[activeItem.id] : undefined;
  const activeGrade = activeItem ? state.grades[activeItem.id] : undefined;

  const goNext = (event: React.MouseEvent<HTMLButtonElement>): void => {
    event.preventDefault();
    if (nextItem) dispatch({ type: "go-to", itemId: nextItem.id });
  };

  const complete = (event: React.MouseEvent<HTMLButtonElement>): void => {
    event.preventDefault();
    dispatch({ type: "complete" });
  };

  return (
    <Questionnaire
      item={formName(props.idPrefix, state.activeItemId)}
      items={questionnaireItems}
      shortcuts="letters"
      onItemChange={(itemName) => {
        const itemId = itemNameFromFormName(props.idPrefix, itemName);
        if (itemId) dispatch({ type: "go-to", itemId });
      }}
      onSubmit={(event) => {
        event.preventDefault();
        dispatch({ type: "complete" });
      }}
      onKeyDown={(event) => {
        if (
          event.defaultPrevented ||
          event.nativeEvent.isComposing ||
          event.keyCode === 229 ||
          event.repeat ||
          event.metaKey ||
          event.ctrlKey ||
          event.altKey ||
          event.shiftKey
        ) {
          return;
        }

        if (
          (event.key === "ArrowLeft" || event.key === "ArrowRight") &&
          (isEditingControl(event.target) || isRadioInput(event.target))
        ) {
          return;
        }

        if (
          event.key === "ArrowRight" &&
          activeItem &&
          (activeItem.type === "info" || activeGrade) &&
          nextItem
        ) {
          event.preventDefault();
          dispatch({ type: "go-to", itemId: nextItem.id });
          return;
        }

        if (
          event.key !== "Enter" ||
          !activeItem ||
          activeItem.type === "info" ||
          activeGrade ||
          !hasAnswer(activeAnswer) ||
          !(event.target instanceof HTMLInputElement) ||
          event.target.name !== formName(props.idPrefix, activeItem.id)
        ) {
          return;
        }

        event.preventDefault();
        dispatch({ type: "submit", itemId: activeItem.id });
      }}
    >
      <Card>
        <CardHeader>
          <CardTitle>{props.quiz.title}</CardTitle>
          <CardAction>
            <span className="font-medium text-muted-foreground tabular-nums">
              {activeQuestionIndex === undefined ? "Information" : `Question ${activeQuestionIndex}`}
            </span>
          </CardAction>
        </CardHeader>
        <CardContent>
          <nav aria-label="Quiz questions" className="mb-6 grid grid-cols-[repeat(auto-fill,2.75rem)] gap-2">
            {questions.map((question, index) => (
              <Button
                key={question.id}
                type="button"
                variant={state.activeItemId === question.id ? "default" : "outline"}
                className="size-11 p-0 tabular-nums"
                aria-label={`Question ${question.index ?? index + 1}`}
                aria-current={state.activeItemId === question.id ? "step" : undefined}
                onClick={() => dispatch({ type: "jump-to", itemId: question.id })}
              >
                {question.index ?? index + 1}
              </Button>
            ))}
          </nav>
          {props.quiz.items.map((item, index) => (
            <QuizStep
              key={item.id}
              domId={`${props.idPrefix}-step-${index}`}
              formName={formName(props.idPrefix, item.id)}
              item={item}
              answer={state.answers[item.id]}
              grade={state.grades[item.id]}
              hintVisible={state.visibleHints.includes(item.id)}
              onAnswer={(answer: SubmittedAnswer) =>
                dispatch({ type: "answer", itemId: item.id, answer })
              }
              onToggleHint={() =>
                dispatch({ type: "toggle-hint", itemId: item.id })
              }
            />
          ))}
        </CardContent>
        <CardFooter className="flex-col gap-3 border-t pt-6">
          {canComplete && nextItem ? (
            <Button type="button" className="self-end" onClick={complete}>
              View results
            </Button>
          ) : null}
          <QuestionnaireActions>
            <QuestionnairePrevious />
            {activeItem?.type === "info" ? (
              nextItem ? (
                <QuestionnaireNext onClick={goNext}>Continue</QuestionnaireNext>
              ) : (
                <QuestionnaireSubmit type="button" disabled={!canComplete} onClick={complete}>
                  View results
                </QuestionnaireSubmit>
              )
            ) : activeGrade ? (
              nextItem ? (
                <QuestionnaireNext onClick={goNext}>Next</QuestionnaireNext>
              ) : (
                <QuestionnaireSubmit type="button" disabled={!canComplete} onClick={complete}>
                  View results
                </QuestionnaireSubmit>
              )
            ) : activeItem ? (
              <Button
                type="button"
                className="col-start-3 row-start-1 min-h-11 justify-self-end sm:min-h-0"
                disabled={!hasAnswer(activeAnswer)}
                onClick={() =>
                  dispatch({ type: "submit", itemId: activeItem.id })
                }
              >
                Check answer
              </Button>
            ) : null}
          </QuestionnaireActions>
        </CardFooter>
      </Card>
    </Questionnaire>
  );
}

function isValidQuiz(quiz: QuizDefinition): boolean {
  try {
    return validateQuizDefinition(quiz).length === 0;
  } catch {
    return false;
  }
}

function quizSessionKey(quiz: QuizDefinition): string {
  return JSON.stringify([
    quiz.id,
    quiz.items.map((item) => {
      if (item.type === "info") return [item.type, item.id];
      if (item.type === "freetext") {
        return [
          item.type,
          item.id,
          item.answer.expected,
          item.answer.caseSensitive ?? false,
        ];
      }

      return [
        item.type,
        item.id,
        item.choices.map((choice) => [choice.id, choice.correct]),
      ];
    }),
  ]);
}

function hasAnswer(answer: SubmittedAnswer | undefined): boolean {
  return typeof answer === "string"
    ? answer.trim().length > 0
    : Array.isArray(answer) && answer.length > 0;
}

function isEditingControl(target: EventTarget): boolean {
  if (
    target instanceof HTMLTextAreaElement ||
    target instanceof HTMLSelectElement
  ) {
    return true;
  }

  if (target instanceof HTMLInputElement) {
    return !["button", "checkbox", "radio", "reset", "submit"].includes(
      target.type,
    );
  }

  return target instanceof HTMLElement && target.isContentEditable;
}

function isRadioInput(target: EventTarget): boolean {
  return target instanceof HTMLInputElement && target.type === "radio";
}

function toQuestionnaireItem(
  item: QuizItem,
  locked: boolean,
  name: string,
): {
  name: string;
  required?: boolean;
  choices?: Array<{ value: string; disabled?: boolean }>;
} {
  if (item.type === "info" || item.type === "freetext") {
    return { name, required: item.type === "freetext" };
  }

  return {
    name,
    required: true,
    choices: item.choices.map((choice) => ({
      value: choice.id,
      disabled: locked,
    })),
  };
}

function formName(idPrefix: string, itemId: string): string {
  return `${idPrefix}-${itemId}`;
}

function itemNameFromFormName(
  idPrefix: string,
  name: string,
): string | undefined {
  const prefix = `${idPrefix}-`;
  return name.startsWith(prefix) ? name.slice(prefix.length) : undefined;
}

function findStep(root: HTMLElement | null, itemId: string): HTMLElement | null {
  if (!root) return null;
  return (
    Array.from(root.querySelectorAll<HTMLElement>("[data-quiz-step]")).find(
      (step) => step.dataset.quizStep === itemId,
    ) ?? null
  );
}

import type React from "react";

import type {
  GradeResult,
  QuizItem,
  QuizQuestion,
  SubmittedAnswer,
} from "../lib/model";
import { Button } from "../ui/primitives";
import {
  QuestionnaireChoice,
  QuestionnaireChoices,
  QuestionnaireDescription,
  QuestionnaireInput,
  QuestionnaireItem,
  QuestionnaireTitle,
} from "../ui/Questionnaire";
import { cn } from "../lib/cn";

interface QuizStepProps {
  domId: string;
  formName: string;
  item: QuizItem;
  answer?: SubmittedAnswer;
  grade?: GradeResult;
  hintVisible: boolean;
  onAnswer: (answer: SubmittedAnswer) => void;
  onToggleHint: () => void;
}

export function QuizStep(props: QuizStepProps): React.JSX.Element {
  const headingId = `${props.domId}-title`;

  if (props.item.type === "info") {
    return (
      <QuestionnaireItem
        name={props.formName}
        aria-labelledby={headingId}
        data-quiz-step={props.item.id}
      >
        <QuestionnaireTitle id={headingId} className="sr-only">
          Information
        </QuestionnaireTitle>
        <QuestionnaireDescription
          render={<div />}
          className="max-w-none text-foreground"
        >
          {props.item.content}
        </QuestionnaireDescription>
      </QuestionnaireItem>
    );
  }

  const locked = props.grade !== undefined;
  return (
    <QuestionnaireItem
      name={props.formName}
      multiple={props.item.type === "multi"}
      required
      aria-labelledby={headingId}
      data-quiz-step={props.item.id}
    >
      <QuestionnaireTitle
        id={headingId}
        render={<div />}
        className="mb-5 text-base font-medium text-foreground"
      >
        {props.item.prompt}
      </QuestionnaireTitle>

      {props.item.type === "freetext" ? (
        <QuestionnaireInput
          aria-labelledby={headingId}
          value={typeof props.answer === "string" ? props.answer : ""}
          disabled={locked}
          onInput={(event) => props.onAnswer(event.currentTarget.value)}
        />
      ) : (
        <ChoiceAnswers
          domId={props.domId}
          question={props.item}
          answer={props.answer}
          grade={props.grade}
          onAnswer={props.onAnswer}
        />
      )}

      {props.item.hint !== undefined ? (
        <div className="mt-4">
          <Button
            type="button"
            variant="outline"
            size="sm"
            aria-expanded={props.hintVisible}
            aria-controls={`${props.domId}-hint`}
            onClick={props.onToggleHint}
          >
            {props.hintVisible ? "Hide hint" : "Show hint"}
          </Button>
          {props.hintVisible ? (
            <div
              id={`${props.domId}-hint`}
              className="mt-3 rounded-lg border bg-muted/40 p-3 text-sm"
            >
              {props.item.hint}
            </div>
          ) : null}
        </div>
      ) : null}

      {props.grade ? (
        <Feedback question={props.item} grade={props.grade} />
      ) : null}
    </QuestionnaireItem>
  );
}

function ChoiceAnswers(props: {
  domId: string;
  question: Exclude<QuizQuestion, { type: "freetext" }>;
  answer?: SubmittedAnswer;
  grade?: GradeResult;
  onAnswer: (answer: SubmittedAnswer) => void;
}): React.JSX.Element {
  const locked = props.grade !== undefined;

  return (
    <QuestionnaireChoices>
      {props.question.choices.map((choice, index) => {
        const checked =
          props.question.type === "multi"
            ? Array.isArray(props.answer) && props.answer.includes(choice.id)
            : props.answer === choice.id;
        const selectedWrong = Boolean(props.grade && checked && !choice.correct);

        return (
          <QuestionnaireChoice
            key={choice.id}
            labelId={`${props.domId}-choice-${index}-label`}
            value={choice.id}
            checked={checked}
            disabled={locked}
            className={cn(
              props.grade && choice.correct && "border-primary bg-primary/10",
              selectedWrong && "border-destructive bg-destructive/10",
            )}
            onChange={(event) => {
              if (props.question.type === "multi") {
                const current = Array.isArray(props.answer) ? props.answer : [];
                props.onAnswer(
                  event.currentTarget.checked
                    ? [...new Set([...current, choice.id])]
                    : current.filter((id) => id !== choice.id),
                );
              } else {
                props.onAnswer(choice.id);
              }
            }}
          >
            {choice.content}
          </QuestionnaireChoice>
        );
      })}
    </QuestionnaireChoices>
  );
}

function Feedback(props: {
  question: QuizQuestion;
  grade: GradeResult;
}): React.JSX.Element {
  return (
    <div
      className={cn(
        "mt-5 rounded-lg border p-4 text-sm",
        props.grade.correct
          ? "border-primary/50 bg-primary/5"
          : "border-destructive/50 bg-destructive/5",
      )}
      role="status"
      aria-live="polite"
    >
      <p className="font-semibold">
        {props.grade.correct ? "Correct." : "Incorrect."}
      </p>
      {!props.grade.correct ? (
        props.question.type === "freetext" ? (
          <p className="mt-1 text-muted-foreground">
            Expected answer: {props.question.answer.expected}
          </p>
        ) : (
          <div className="mt-1 text-muted-foreground">
            <div>Expected answer:</div>
            <ExpectedAnswer question={props.question} />
          </div>
        )
      ) : null}
      {props.question.explanation !== undefined ? (
        <div className="mt-3 border-t pt-3 text-foreground">
          {props.question.explanation}
        </div>
      ) : null}
    </div>
  );
}

function ExpectedAnswer(props: {
  question: Exclude<QuizQuestion, { type: "freetext" }>;
}): React.JSX.Element {
  const correctChoices = props.question.choices.filter(
    (choice) => choice.correct,
  );
  return (
    <ul
      data-slot="quiz-expected-answers"
      className="m-0 flex list-none flex-col gap-1 p-0"
    >
      {correctChoices.map((choice) => (
        <li key={choice.id} data-slot="quiz-expected-answer">
          {choice.content}
        </li>
      ))}
    </ul>
  );
}

import type React from "react";

import type { GradeResult, QuizDefinition, QuizQuestion } from "../lib/model";
import {
  Button,
  Card,
  CardContent,
  CardFooter,
  CardHeader,
  CardTitle,
} from "../ui/primitives";

interface QuizResultsProps {
  definition: QuizDefinition;
  grades: Readonly<Record<string, GradeResult>>;
  onRestart: () => void;
  headingRef?: React.Ref<HTMLHeadingElement>;
}

export function QuizResults(props: QuizResultsProps): React.JSX.Element {
  const questions = props.definition.items.filter(isQuestion);
  const correct = questions.filter(
    (question) => props.grades[question.id]?.correct,
  ).length;

  return (
    <Card>
      <CardHeader>
        <CardTitle>
          <h3 ref={props.headingRef} tabIndex={-1} className="outline-none">
            {props.definition.title}: results
          </h3>
        </CardTitle>
        <p className="text-2xl font-semibold tabular-nums">
          {correct} / {questions.length}
        </p>
      </CardHeader>
      <CardContent>
        <ul className="space-y-2">
          {questions.map((question, index) => (
            <li
              key={question.id}
              className="flex items-start justify-between gap-4 rounded-lg border p-3 text-sm"
            >
              <div>
                {question.index ?? index + 1}. {question.prompt}
              </div>
              <span className="shrink-0 font-medium">
                {props.grades[question.id]?.correct ? "Correct" : "Incorrect"}
              </span>
            </li>
          ))}
        </ul>
      </CardContent>
      <CardFooter>
        <Button type="button" onClick={props.onRestart}>
          Restart quiz
        </Button>
      </CardFooter>
    </Card>
  );
}

function isQuestion(item: QuizDefinition["items"][number]): item is QuizQuestion {
  return item.type !== "info";
}

"use client";

import { Questionnaire as QuestionnairePrimitive } from "@shadcn/react/questionnaire";
import * as React from "react";

import { buttonClassName, type ButtonProps } from "./primitives";
import { cn } from "../lib/cn";

export function Questionnaire({
  className,
  ...props
}: React.ComponentProps<typeof QuestionnairePrimitive.Root>): React.JSX.Element {
  return (
    <QuestionnairePrimitive.Root
      data-slot="questionnaire"
      className={cn("cn-questionnaire flex w-full min-w-0 flex-col", className)}
      {...props}
    />
  );
}

export function QuestionnaireProgress({
  className,
  ...props
}: React.ComponentProps<
  typeof QuestionnairePrimitive.Progress
>): React.JSX.Element {
  return (
    <QuestionnairePrimitive.Progress
      data-slot="questionnaire-progress"
      className={cn(
        "min-h-[1lh] w-fit min-w-[14ch] font-medium text-muted-foreground tabular-nums",
        className,
      )}
      {...props}
    />
  );
}

export function QuestionnaireItem({
  className,
  ...props
}: React.ComponentProps<typeof QuestionnairePrimitive.Item>): React.JSX.Element {
  return (
    <QuestionnairePrimitive.Item
      data-slot="questionnaire-item"
      className={cn("min-w-0 border-0 p-0 outline-none", className)}
      {...props}
    />
  );
}

export function QuestionnaireTitle({
  className,
  ...props
}: React.ComponentProps<
  typeof QuestionnairePrimitive.Title
>): React.JSX.Element {
  return (
    <QuestionnairePrimitive.Title
      data-slot="questionnaire-title"
      className={cn("text-pretty", className)}
      {...props}
    />
  );
}

export function QuestionnaireDescription({
  className,
  ...props
}: React.ComponentProps<
  typeof QuestionnairePrimitive.Description
>): React.JSX.Element {
  return (
    <QuestionnairePrimitive.Description
      data-slot="questionnaire-description"
      className={cn("text-pretty text-muted-foreground", className)}
      {...props}
    />
  );
}

export function QuestionnaireChoices({
  className,
  ...props
}: React.ComponentProps<
  typeof QuestionnairePrimitive.Choices
>): React.JSX.Element {
  return (
    <QuestionnairePrimitive.Choices
      data-slot="questionnaire-choices"
      className={cn("grid min-w-0 gap-2", className)}
      {...props}
    />
  );
}

export function QuestionnaireChoice({
  children,
  className,
  labelId,
  ...props
}: React.ComponentProps<typeof QuestionnairePrimitive.Choice> & {
  labelId: string;
}): React.JSX.Element {
  return (
    <QuestionnairePrimitive.Choice
      render={<div />}
      data-slot="questionnaire-choice"
      className={cn(
        "group/questionnaire-choice relative flex min-h-11 cursor-pointer items-start gap-3 rounded-lg border border-border bg-background px-3 py-2.5 text-start transition-colors outline-none select-none hover:bg-muted/50 focus-within:border-ring focus-within:ring-3 focus-within:ring-ring/50",
        "data-disabled:pointer-events-none data-disabled:cursor-not-allowed data-disabled:opacity-50",
        "data-checked:border-primary data-checked:bg-primary/5",
        className,
      )}
      {...props}
    >
      <QuestionnairePrimitive.ChoiceInput
        aria-labelledby={labelId}
        data-slot="questionnaire-choice-input"
        className="absolute inset-0 z-10 size-full cursor-pointer opacity-0"
      />
      <span
        aria-hidden="true"
        data-slot="questionnaire-choice-indicator"
        className="pointer-events-none relative mt-0.5 flex size-4 shrink-0 items-center justify-center rounded-sm border border-input bg-background group-data-[type=radio]/questionnaire-choice:rounded-full group-data-checked/questionnaire-choice:border-primary group-data-checked/questionnaire-choice:bg-primary group-data-checked/questionnaire-choice:text-primary-foreground"
      >
        <span className="hidden size-1.5 rounded-full bg-current group-data-[type=checkbox]/questionnaire-choice:hidden group-data-checked/questionnaire-choice:block" />
        <svg
          viewBox="0 0 16 16"
          fill="none"
          stroke="currentColor"
          strokeWidth="2"
          strokeLinecap="round"
          strokeLinejoin="round"
          className="hidden size-3 group-data-[type=radio]/questionnaire-choice:hidden group-data-checked/questionnaire-choice:block"
        >
          <path d="m3 8 3 3 7-7" />
        </svg>
      </span>
      <QuestionnairePrimitive.ChoiceLabel
        render={<div id={labelId} />}
        data-slot="questionnaire-choice-label"
        className="flex min-w-0 flex-1 flex-col leading-snug"
      >
        {children}
      </QuestionnairePrimitive.ChoiceLabel>
      <QuestionnairePrimitive.ChoiceShortcut
        data-slot="questionnaire-choice-shortcut"
        className="pointer-events-none ms-auto hidden shrink-0 group-data-[shortcut]/questionnaire-choice:inline-flex"
      />
    </QuestionnairePrimitive.Choice>
  );
}

export function QuestionnaireInput({
  className,
  ...props
}: React.ComponentProps<
  typeof QuestionnairePrimitive.Input
>): React.JSX.Element {
