import type { ReactNode } from "react";

export interface QuizDefinition {
  id: string;
  title: string;
  items: QuizItem[];
}

export interface QuizInfo {
  type: "info";
  id: string;
  content: ReactNode;
}

export interface QuizChoice {
  id: string;
  content: ReactNode;
  correct: boolean;
}

interface QuizQuestionBase {
  index?: number;
  id: string;
  prompt: ReactNode;
  hint?: ReactNode;
  explanation?: ReactNode;
}

export interface SingleChoiceQuestion extends QuizQuestionBase {
  type: "single";
  choices: QuizChoice[];
}

export interface MultipleChoiceQuestion extends QuizQuestionBase {
  type: "multi";
  choices: QuizChoice[];
}

export interface TrueFalseQuestion extends QuizQuestionBase {
  type: "truefalse";
  choices: QuizChoice[];
}

export interface FreeTextQuestion extends QuizQuestionBase {
  type: "freetext";
  answer: {
    expected: string;
    caseSensitive?: boolean;
  };
}

export type QuizQuestion =
  | SingleChoiceQuestion
  | MultipleChoiceQuestion
  | TrueFalseQuestion
  | FreeTextQuestion;

export type QuizItem = QuizInfo | QuizQuestion;

export type SubmittedAnswer = string | string[];

export interface GradeResult {
  correct: boolean;
  submitted: SubmittedAnswer;
  expected: SubmittedAnswer;
  error?: "invalid-answer-shape" | "unknown-choice";
}

export interface QuizResult {
  correct: number;
  total: number;
  answers: Readonly<Record<string, SubmittedAnswer>>;
  grades: Readonly<Record<string, GradeResult>>;
}

import type {
  GradeResult,
  QuizDefinition,
  QuizQuestion,
  QuizResult,
  SubmittedAnswer,
} from "./model";

export function gradeAnswer(
  question: QuizQuestion,
  submitted: SubmittedAnswer,
): GradeResult {
  switch (question.type) {
    case "single":
    case "truefalse":
      return gradeSingleChoice(question, submitted);
    case "multi":
      return gradeMultipleChoice(question, submitted);
    case "freetext":
      return gradeFreeText(question, submitted);
  }
}

export function scoreQuiz(
  definition: QuizDefinition,
  answers: Readonly<Record<string, SubmittedAnswer>>,
): QuizResult {
  const grades = Object.fromEntries(
    definition.items
      .filter((item): item is QuizQuestion => item.type !== "info")
      .flatMap((question) => {
        const submitted = answers[question.id];
        return submitted === undefined
          ? []
          : [[question.id, gradeAnswer(question, submitted)]];
      }),
  ) as Record<string, GradeResult>;

  const questions = definition.items.filter(
    (item): item is QuizQuestion => item.type !== "info",
  );

  return {
    correct: questions.filter((question) => grades[question.id]?.correct).length,
    total: questions.length,
    answers,
    grades,
  };
}

function gradeSingleChoice(
  question: Extract<QuizQuestion, { type: "single" | "truefalse" }>,
  submitted: SubmittedAnswer,
): GradeResult {
  const expected = question.choices.find((choice) => choice.correct)?.id ?? "";

  if (typeof submitted !== "string") {
    return invalid(submitted, expected, "invalid-answer-shape");
  }

  if (!question.choices.some((choice) => choice.id === submitted)) {
    return invalid(submitted, expected, "unknown-choice");
  }

  return {
    correct: submitted === expected,
    submitted,
    expected,
  };
}

function gradeMultipleChoice(
  question: Extract<QuizQuestion, { type: "multi" }>,
  submitted: SubmittedAnswer,
): GradeResult {
  const expected = question.choices
    .filter((choice) => choice.correct)
    .map((choice) => choice.id)
    .sort();

  if (!Array.isArray(submitted) || !submitted.every((value) => typeof value === "string")) {
    return invalid(submitted, expected, "invalid-answer-shape");
  }

  const known = new Set(question.choices.map((choice) => choice.id));
  if (submitted.some((value) => !known.has(value))) {
    return invalid(submitted, expected, "unknown-choice");
  }

  const normalized = [...new Set(submitted)].sort();

  return {
    correct:
      normalized.length === expected.length &&
      normalized.every((value, index) => value === expected[index]),
    submitted: normalized,
    expected,
  };
}

function gradeFreeText(
  question: Extract<QuizQuestion, { type: "freetext" }>,
  submitted: SubmittedAnswer,
): GradeResult {
  if (typeof submitted !== "string") {
    return invalid(submitted, question.answer.expected, "invalid-answer-shape");
  }

  const options = { caseSensitive: question.answer.caseSensitive };
  const normalizedSubmitted = normalizeFreeText(submitted, options);
  const normalizedExpected = normalizeFreeText(question.answer.expected, options);

  return {
    correct: normalizedSubmitted === normalizedExpected,
    submitted: normalizedSubmitted,
    expected: normalizedExpected,
  };
}

function normalizeFreeText(
  value: string,
  options: { caseSensitive?: boolean } = {},
): string {
  const normalized = value.trim().replace(/\s+/g, " ");
  return options.caseSensitive ? normalized : normalized.toLocaleLowerCase();
}

function invalid(
  submitted: SubmittedAnswer,
  expected: SubmittedAnswer,
  error: NonNullable<GradeResult["error"]>,
): GradeResult {
  return {
    correct: false,
    submitted,
    expected,
    error,
  };
}

import { gradeAnswer } from "./grading";
import type {
  GradeResult,
  QuizDefinition,
  QuizQuestion,
  SubmittedAnswer,
} from "./model";

export interface QuizSessionState {
  activeItemId: string;
  answers: Record<string, SubmittedAnswer>;
  grades: Record<string, GradeResult>;
  visibleHints: string[];
  phase: "active" | "complete";
}

export type QuizSessionAction =
  | { type: "answer"; itemId: string; answer: SubmittedAnswer }
  | { type: "toggle-hint"; itemId: string }
  | { type: "submit"; itemId: string }
  | { type: "jump-to"; itemId: string }
  | { type: "go-to"; itemId: string }
  | { type: "complete" }
  | { type: "restart" };

export function createQuizSession(definition: QuizDefinition): QuizSessionState {
  return {
    activeItemId: definition.items[0]?.id ?? "",
    answers: {},
    grades: {},
    visibleHints: [],
    phase: definition.items.length > 0 ? "active" : "complete",
  };
}

export function reduceQuizSession(
  definition: QuizDefinition,
  state: QuizSessionState,
  action: QuizSessionAction,
): QuizSessionState {
  if (action.type === "restart") {
    return createQuizSession(definition);
  }

  if (state.phase === "complete") {
    return state;
  }

  switch (action.type) {
    case "answer": {
      const question = findQuestion(definition, action.itemId);

      if (
        question === undefined ||
        action.itemId !== state.activeItemId ||
        state.grades[action.itemId] !== undefined
      ) {
        return state;
      }

      return {
        ...state,
        answers: {
          ...state.answers,
          [action.itemId]: action.answer,
        },
      };
    }
    case "toggle-hint": {
      const question = findQuestion(definition, action.itemId);

      if (
        question?.hint === undefined ||
        action.itemId !== state.activeItemId
      ) {
        return state;
      }

      const visibleHints = new Set(state.visibleHints);

      if (visibleHints.has(action.itemId)) {
        visibleHints.delete(action.itemId);
      } else {
        visibleHints.add(action.itemId);
      }

      return {
        ...state,
        visibleHints: [...visibleHints],
      };
    }
    case "submit": {
      const question = findQuestion(definition, action.itemId);
      const submitted = state.answers[action.itemId];

      if (
        question === undefined ||
        action.itemId !== state.activeItemId ||
        state.grades[action.itemId] !== undefined ||
        !hasAnswer(submitted)
      ) {
        return state;
      }

      return {
        ...state,
        grades: {
          ...state.grades,
          [action.itemId]: gradeAnswer(question, submitted),
        },
      };
    }
    case "jump-to": {
      if (!findQuestion(definition, action.itemId)) return state;
      return { ...state, activeItemId: action.itemId };
    }
    case "go-to": {
      const currentIndex = definition.items.findIndex(
        (item) => item.id === state.activeItemId,
      );
      const targetIndex = definition.items.findIndex(
        (item) => item.id === action.itemId,
      );

      if (currentIndex < 0 || targetIndex < 0 || currentIndex === targetIndex) {
        return state;
      }

      if (targetIndex < currentIndex) {
        return {
          ...state,
          activeItemId: action.itemId,
        };
      }

      if (targetIndex !== currentIndex + 1) {
        return state;
      }

      const currentItem = definition.items[currentIndex];

      if (
        currentItem !== undefined &&
        isQuestion(currentItem) &&
        state.grades[currentItem.id] === undefined
      ) {
        return state;
      }

      return {
        ...state,
        activeItemId: action.itemId,
      };
    }
    case "complete": {
      const allQuestionsGraded = definition.items
        .filter(isQuestion)
        .every((question) => state.grades[question.id] !== undefined);

      if (!allQuestionsGraded) {
        return state;
      }

      return {
        ...state,
        phase: "complete",
      };
    }
  }
}

function hasAnswer(answer: SubmittedAnswer | undefined): answer is SubmittedAnswer {
  if (typeof answer === "string") {
    return answer.trim().length > 0;
  }

  return Array.isArray(answer) && answer.length > 0;
}

function findQuestion(
  definition: QuizDefinition,
  itemId: string,
): QuizQuestion | undefined {
  const item = definition.items.find((candidate) => candidate.id === itemId);
  return item !== undefined && isQuestion(item) ? item : undefined;
}

function isQuestion(item: QuizDefinition["items"][number]): item is QuizQuestion {
  return item.type !== "info";
}

import type { QuizChoice, QuizDefinition, QuizItem, QuizQuestion } from "./model";

export interface QuizValidationIssue {
  code: string;
  message: string;
}

export function validateQuizDefinition(
  quiz: QuizDefinition,
): readonly QuizValidationIssue[] {
  const issues: QuizValidationIssue[] = [];

  if (!quiz.id.trim()) {
    issues.push(issue("quiz.id.empty", "Quiz ID must not be empty."));
  }

  if (quiz.items.length === 0) {
    issues.push(issue("quiz.items.empty", "Quiz must contain at least one item."));
  }

  if (!quiz.items.some(isQuestion)) {
    issues.push(issue("quiz.question.missing", "Quiz must contain at least one question."));
  }

  const itemIds = new Set<string>();
  for (const item of quiz.items) {
    if (!item.id.trim()) {
      issues.push(issue("quiz.item.id.empty", "Quiz item ID must not be empty."));
    } else if (itemIds.has(item.id)) {
      issues.push(
        issue("quiz.item.id.duplicate", `Quiz item ID "${item.id}" must be unique.`),
      );
    } else {
      itemIds.add(item.id);
    }

    if (item.type !== "info") {
      validateQuestion(item, issues);
    }
  }

  return issues;
}

function validateQuestion(
  question: QuizQuestion,
  issues: QuizValidationIssue[],
): void {
  if (question.index !== undefined && (!Number.isSafeInteger(question.index) || question.index < 1)) {
    issues.push(issue("quiz.question.index", "Question index must be a positive integer."));
  }
  if (question.type === "freetext") {
    if (!question.answer.expected.trim()) {
      issues.push(
        issue(
          "quiz.freetext.answer.empty",
          `Free-text question "${question.id}" must define a non-empty expected answer.`,
        ),
      );
    }
    return;
  }

  validateChoiceIds(question.choices, issues);

  const correctCount = question.choices.filter((choice) => choice.correct).length;
  if (question.type === "single" && correctCount !== 1) {
    issues.push(
      issue(
        "quiz.single.correct-count",
        `Single-choice question "${question.id}" must have exactly one correct choice.`,
      ),
    );
  }

  if (question.type === "multi" && correctCount < 1) {
    issues.push(
      issue(
        "quiz.multi.correct-count",
        `Multiple-choice question "${question.id}" must have at least one correct choice.`,
      ),
    );
  }

  if (question.type === "truefalse") {
    const labels = question.choices.map(normalizedTrueFalseLabel);
    const validLabels =
      question.choices.length === 2 &&
      labels.includes("true") &&
      labels.includes("false") &&
      labels.every((label) => label !== null);

    if (!validLabels) {
      issues.push(
        issue(
          "quiz.truefalse.shape",
          `True/false question "${question.id}" must contain exactly two plain-string choices labeled True and False.`,
        ),
      );
    }

    if (correctCount !== 1) {
      issues.push(
        issue(
          "quiz.truefalse.correct-count",
          `True/false question "${question.id}" must have exactly one correct choice.`,
        ),
      );
    }
  }
}

function validateChoiceIds(
  choices: QuizChoice[],
  issues: QuizValidationIssue[],
): void {
  const choiceIds = new Set<string>();

  for (const choice of choices) {
    if (!choice.id.trim()) {
      issues.push(
        issue("quiz.choice.id.empty", "Choice ID must not be empty."),
      );
    } else if (choiceIds.has(choice.id)) {
      issues.push(
        issue(
          "quiz.choice.id.duplicate",
          `Choice ID "${choice.id}" must be unique within a question.`,
        ),
      );
    } else {
      choiceIds.add(choice.id);
    }
  }
}

function normalizedTrueFalseLabel(choice: QuizChoice): string | null {
  return typeof choice.content === "string" ? choice.content.trim().toLowerCase() : null;
}

function isQuestion(item: QuizItem): item is QuizQuestion {
  return item.type !== "info";
}

function issue(code: string, message: string): QuizValidationIssue {
  return { code, message };
}

